{"command":"cd /work && printf '%s\n' '{
  "services": {
    "api": {
      "timeout_seconds": 20,
      "host": "127.0.0.1",
      "retries": 3
    },
    "worker": {
      "timeout_seconds": 60
    }
  },
  "auth": {
    "token": "SYNTHETIC-NOT-A-REAL-SECRET"
  },
  "features": [
    "a",
    "b"
  ]
}' > /work/.orig_check.json && python3 -c "
import json
new=json.load(open('services.json')); old=json.load(open('.orig_check.json'))
def flat(d,p=''):
    out={}
    for k,v in d.items():
        kk=f'{p}.{k}'
        if isinstance(v,dict): out.update(flat(v,kk))
        else: out[kk]=v
    return out
a,b=flat(old),flat(new)
print('changed:', {k:(a[k],b[k]) for k in a if a[k]!=b.get(k)})
print('key diff:', set(a)^set(b))
print('api.timeout_seconds =', new['services']['api']['timeout_seconds'])
print('worker.timeout_seconds =', new['services']['worker']['timeout_seconds'], '| api.host =', new['services']['api']['host'], '| api.retries =', new['services']['api']['retries'])
print('auth.token =', new['auth']['token'], '| features =', new['features'])
"; rm -f /work/.orig_check.json; ls -la /work"}

